using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.FNZ.Cuentas{    [SwaggerSchema("Modelo de lectura de un Cuenta")]    [GraphQLDescription("Objeto que representa un Cuenta existente.")]    public class clReadCuentas    {        [SwaggerSchema("Identificador único del Cuenta")]        [GraphQLDescription("Identificador único del Cuenta")]        public int? CuentaID { get; set; }        [SwaggerSchema("Cuenta")]        [GraphQLDescription("Cuenta")]        public string? Cuenta { get; set; } = default!;        [SwaggerSchema("Tipo")]        [GraphQLDescription("Tipo")]        public string? Tipo { get; set; } = default!;        [SwaggerSchema("Saldo")]        [GraphQLDescription("Saldo")]        public decimal? Saldo { get; set; }        [SwaggerSchema("ResponsableUsuarioID")]        [GraphQLDescription("ResponsableUsuarioID")]        public int? ResponsableUsuarioID { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un Cuenta")]    [GraphQLDescription("Input para crear un Cuenta.")]    public class clCreateCuentas    {        [GraphQLNonNullType] [SwaggerSchema("Cuenta")]        [GraphQLDescription("Cuenta")]        public string Cuenta { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("Tipo")]        [GraphQLDescription("Tipo")]        public string Tipo { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("Saldo")]        [GraphQLDescription("Saldo")]        public decimal Saldo { get; set; }        [SwaggerSchema("ResponsableUsuarioID")]        [GraphQLDescription("ResponsableUsuarioID")]        public int? ResponsableUsuarioID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un Cuenta")]    [GraphQLDescription("Input para actualizar parcialmente un Cuenta.")]    public class clUpdateCuentas    {        [SwaggerSchema("Identificador único del Cuenta")]        [GraphQLDescription("Identificador único del Cuenta")]        public int? CuentaID { get; set; }        [SwaggerSchema("Cuenta")]        [GraphQLDescription("Cuenta")]        public string? Cuenta { get; set; }        [SwaggerSchema("Tipo")]        [GraphQLDescription("Tipo")]        public string? Tipo { get; set; }        [SwaggerSchema("Saldo")]        [GraphQLDescription("Saldo")]        public decimal? Saldo { get; set; }        [SwaggerSchema("ResponsableUsuarioID")]        [GraphQLDescription("ResponsableUsuarioID")]        public int? ResponsableUsuarioID { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}